export const SETUP_SH_BODY = "# Floway agent setup installer (Bash 3.2+). The gateway prepends the\n# language-native assignment prefix, so this fixed body has no shebang.\n#\n# Each selected agent is an independent transaction. Errexit stays disabled\n# because Bash suppresses it inside the aggregation guards at the bottom;\n# failures are checked explicitly and rolled back per agent.\n\nset -u\numask 077\nset -o pipefail 2>/dev/null || true\n\n# The API key remains a shell variable, not an exported process-environment\n# value. `export -n` also neutralizes an identically named exported variable\n# inherited from the caller. jq/awk receive it only on the individual\n# invocations that need it; the official installer and Claude CLI never inherit\n# it.\nexport -n FLOWAY_API_KEY 2>/dev/null || true\n\n# --- output layer -----------------------------------------------------------\n#\n# Structure is carried by a compact box-line tree, not banners or padded\n# columns: a blank line then `┌─ <name>` opens a phase, `│  ` continues its\n# body, `│  · ` marks a step, and the closing Summary phase lists each agent as\n# `<label>  [state]`. The PowerShell installer prints the identical text and the\n# same color semantics through its native host colors.\n#\n# Color is emitted only for an interactive terminal with NO_COLOR unset, probed\n# per stream so a redirected capture on either stdout or stderr stays free of\n# escape sequences. Informational, progress, and success lines go to stdout;\n# warnings, errors, rollback notices, and captured tool output go to stderr.\n_floway_stream_color() {\n  [ -z \"${NO_COLOR:-}\" ] || return 1\n  [ -n \"${FLOWAY_INSTALLER_TEST_FORCE_COLOR:-}\" ] && return 0\n  [ -t \"$1\" ]\n}\nif _floway_stream_color 1; then _OUT_COLOR=1; else _OUT_COLOR=0; fi\nif _floway_stream_color 2; then _ERR_COLOR=1; else _ERR_COLOR=0; fi\n_C_CYAN=$'\\033[96m'\n_C_DARK_CYAN=$'\\033[36m'\n_C_GREEN=$'\\033[92m'\n_C_YELLOW=$'\\033[93m'\n_C_RED=$'\\033[91m'\n_C_GRAY=$'\\033[90m'\n_C_RESET=$'\\033[0m'\n\n# Emit one line to a stream, wrapping it in an ANSI color only when that stream\n# opted into color and a non-empty color was given (default-color lines, like\n# tree detail, stay uncolored rather than carrying a bare reset). $1 stream\n# (1|2), $2 color, $3 text.\n_emit_line() {\n  if [ \"$1\" -eq 1 ]; then\n    if [ \"$_OUT_COLOR\" -eq 1 ] && [ -n \"$2\" ]; then printf '%s%s%s\\n' \"$2\" \"$3\" \"$_C_RESET\"; else printf '%s\\n' \"$3\"; fi\n  else\n    if [ \"$_ERR_COLOR\" -eq 1 ] && [ -n \"$2\" ]; then printf '%s%s%s\\n' \"$2\" \"$3\" \"$_C_RESET\" >&2; else printf '%s\\n' \"$3\" >&2; fi\n  fi\n}\n\nout_title() { _emit_line 1 \"$_C_CYAN\" 'Floway agent setup'; }\nout_phase() { printf '\\n'; _emit_line 1 \"$_C_CYAN\" \"┌─ $1\"; }\nout_step() { _emit_line 1 \"$_C_DARK_CYAN\" \"│  · $1\"; }\nout_info() { _emit_line 1 '' \"│  $1\"; }\nout_success() { _emit_line 1 \"$_C_GREEN\" \"│  $1\"; }\nout_warn() { _emit_line 2 \"$_C_YELLOW\" \"│  $1\"; }\nout_error() { _emit_line 2 \"$_C_RED\" \"│  $1\"; }\n# A fatal line raised before any phase is open carries no spine.\nout_fatal() { _emit_line 2 \"$_C_RED\" \"$1\"; }\n\n# Re-emit captured official-tool output as a de-emphasized, redacted, spined\n# block on stderr so it never masquerades as a Floway line.\nout_captured() {\n  redact_key | while IFS= read -r _oc_line; do\n    _emit_line 2 \"$_C_GRAY\" \"│    $_oc_line\"\n  done\n}\n\nout_summary_entry() {\n  case \"$2\" in\n    configured) _os_color=$_C_GREEN ;;\n    failed) _os_color=$_C_RED ;;\n    *) _os_color=$_C_GRAY ;;\n  esac\n  _emit_line 1 \"$_os_color\" \"│  $1  [$2]\"\n}\n\nout_title\n\n# The wrapping command supplies FLOWAY_BASE_URL. Validate it before mutation,\n# then keep it out of installer and CLI subprocess environments.\nif [ -z \"${FLOWAY_BASE_URL:-}\" ]; then\n  out_fatal 'FLOWAY_BASE_URL must be set to this gateway origin (e.g. https://gateway.example).'\n  exit 1\nfi\ncase \"$FLOWAY_BASE_URL\" in\n  http://?* | https://?*) ;;\n  *)\n    out_fatal \"FLOWAY_BASE_URL must be an http(s) origin, got $FLOWAY_BASE_URL\"\n    exit 1\n    ;;\nesac\nexport -n FLOWAY_BASE_URL 2>/dev/null || true\n\nFLOWAY_SETUP_TMPDIR=\"\"\n_cleanup() {\n  if [ -n \"$FLOWAY_SETUP_TMPDIR\" ]; then\n    rm -rf \"$FLOWAY_SETUP_TMPDIR\" 2>/dev/null || true\n  fi\n}\n# EXIT owns cleanup. INT/TERM only translate the signal into the conventional\n# exit status (130 = 128+SIGINT, 143 = 128+SIGTERM) and let that exit fire the\n# EXIT trap. Cleaning up directly inside the INT/TERM handlers would delete the\n# working directory and then let the interrupted script resume into the next\n# agent's configuration; exiting instead stops all further agent work.\ntrap _cleanup EXIT\ntrap 'exit 130' INT\ntrap 'exit 143' TERM\n\n# Resolved lazily by ensure_jq: either `jq` on PATH or a verified pinned build.\nJQ=\"\"\n\n# Managed-key merge applied to the existing Claude settings document. Only the\n# keys Floway owns are touched; every unrelated key and env var is preserved.\n# An empty optional value means \"remove that managed key\". The API key is read\n# from the environment (`env.FLOWAY_API_KEY`) so it stays out of argv.\nCLAUDE_MERGE_PROGRAM='\n  if type != \"object\" then error(\"root is not a JSON object\")\n  elif (has(\"env\") and ((.env | type) != \"object\")) then error(\"env is not a JSON object\")\n  else . end\n  | (if (has(\"env\") | not) then .env = {} else . end)\n  | .env.ANTHROPIC_BASE_URL = $baseUrl\n  | .env.ANTHROPIC_AUTH_TOKEN = env.FLOWAY_API_KEY\n  | (if $model == \"\" then del(.env.ANTHROPIC_MODEL) else .env.ANTHROPIC_MODEL = $model end)\n  | (if $opus == \"\" then del(.env.ANTHROPIC_DEFAULT_OPUS_MODEL) else .env.ANTHROPIC_DEFAULT_OPUS_MODEL = $opus end)\n  | (if $sonnet == \"\" then del(.env.ANTHROPIC_DEFAULT_SONNET_MODEL) else .env.ANTHROPIC_DEFAULT_SONNET_MODEL = $sonnet end)\n  | (if $haiku == \"\" then del(.env.ANTHROPIC_DEFAULT_HAIKU_MODEL) else .env.ANTHROPIC_DEFAULT_HAIKU_MODEL = $haiku end)\n  | (if $discovery == \"1\" then .env.CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY = \"1\" else del(.env.CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY) end)\n  | (if $effort == \"\" then del(.effortLevel) else .effortLevel = $effort end)\n'\n\n# --- common helpers ---------------------------------------------------------\n\n# Redact every literal occurrence of the API key from a text stream. The key is\n# read from the environment (never argv) and matched with index() so arbitrary\n# key characters are treated literally rather than as a regex.\nredact_key() {\n  FLOWAY_API_KEY=\"$FLOWAY_API_KEY\" awk '\n    BEGIN { k = ENVIRON[\"FLOWAY_API_KEY\"]; kl = length(k) }\n    {\n      if (kl == 0) { print; next }\n      line = $0; out = \"\"\n      while ((p = index(line, k)) > 0) {\n        out = out substr(line, 1, p - 1) \"***\"\n        line = substr(line, p + kl)\n      }\n      print out line\n    }\n  '\n}\n\n# Run a command under a wall-clock limit. macOS ships no `timeout`, so the\n# Bash-3.2 fallback enables job control for one launch, placing the command and\n# all ordinary descendants in a dedicated process group. The watchdog signals\n# that group with TERM then KILL, retains its process-group id across root exit,\n# and the parent waits for escalation to finish before returning 124.\n_run_with_timeout() {\n  _rwt_secs=$1\n  shift\n  if command -v timeout >/dev/null 2>&1; then\n    timeout \"$_rwt_secs\" \"$@\"\n    return $?\n  fi\n  if command -v gtimeout >/dev/null 2>&1; then\n    gtimeout \"$_rwt_secs\" \"$@\"\n    return $?\n  fi\n\n  _rwt_marker=$(mktemp \"$FLOWAY_SETUP_TMPDIR/timeout.XXXXXX\") || return 1\n  rm -f \"$_rwt_marker\"\n  if [ -n \"${FLOWAY_INSTALLER_TEST_TRACE_TIMEOUT:-}\" ]; then\n    printf 'Floway test: timeout fallback: process-tree\\n'\n  fi\n  set -m\n  \"$@\" &\n  _rwt_pid=$!\n  set +m\n  (\n    # The watchdog must not retain the installer's stdout/stderr descriptors\n    # after its parent shell is killed; otherwise a pipe consumer waits for the\n    # orphaned sleep to exit before receiving EOF.\n    exec </dev/null >/dev/null 2>&1\n    sleep \"$_rwt_secs\"\n    if kill -0 \"$_rwt_pid\" 2>/dev/null; then\n      : > \"$_rwt_marker\"\n      kill -TERM -- \"-$_rwt_pid\" 2>/dev/null || true\n      sleep 1\n      kill -KILL -- \"-$_rwt_pid\" 2>/dev/null || true\n    fi\n  ) &\n  _rwt_watchdog=$!\n  wait \"$_rwt_pid\"\n  _rwt_status=$?\n  if [ -e \"$_rwt_marker\" ]; then\n    # The timeout path waits through TERM→KILL escalation; the process-group id\n    # remains valid even after its original leader exits.\n    wait \"$_rwt_watchdog\" 2>/dev/null || true\n    rm -f \"$_rwt_marker\"\n    return 124\n  fi\n  kill \"$_rwt_watchdog\" 2>/dev/null || true\n  wait \"$_rwt_watchdog\" 2>/dev/null || true\n  rm -f \"$_rwt_marker\"\n  return $_rwt_status\n}\n\n# Download the pinned official jq build for this platform into the private\n# working directory and verify its hard-coded SHA-256 before use. Fails on an\n# unsupported platform, a download error, a missing hashing tool, or a checksum\n# mismatch — always before any configuration file is touched.\n_bootstrap_jq() {\n  _bj_os=$(uname -s)\n  _bj_arch=$(uname -m)\n  case \"$_bj_os\" in\n    Darwin) _bj_os_part=macos ;;\n    Linux) _bj_os_part=linux ;;\n    *) out_error \"no pinned jq build for OS $_bj_os.\"; return 1 ;;\n  esac\n  case \"$_bj_arch\" in\n    x86_64 | amd64) _bj_arch_part=amd64 ;;\n    arm64 | aarch64) _bj_arch_part=arm64 ;;\n    *) out_error \"no pinned jq build for architecture $_bj_arch.\"; return 1 ;;\n  esac\n  _bj_asset=\"jq-$_bj_os_part-$_bj_arch_part\"\n  # Pinned to jqlang/jq release jq-1.8.2. Each digest was verified against the\n  # release sha256sum.txt and the Sigstore build attestation\n  # (signer: jqlang/jq .github/workflows/ci.yml@refs/tags/jq-1.8.2).\n  # Ref: https://github.com/jqlang/jq/releases/tag/jq-1.8.2\n  case \"$_bj_asset\" in\n    jq-macos-amd64) _bj_sha=e94b266e3c26690550006abe63152b782280f4e14374accdf04cbde844f00bc0 ;;\n    jq-macos-arm64) _bj_sha=2d75340ba57a4b4b4c8708a21c2dc8e958a48aaa8bba13b27f77f6e4c0eca07e ;;\n    jq-linux-amd64) _bj_sha=b1c22172dd303f3be49e935aa56aa48a8b7a46e0bc838b4997d3bb451495870f ;;\n    jq-linux-arm64) _bj_sha=8b85c817833814ddca00a144c33705546355afccf0cf39b188f3cdb48b852309 ;;\n    *) return 1 ;;\n  esac\n  _bj_url=\"https://github.com/jqlang/jq/releases/download/jq-1.8.2/$_bj_asset\"\n  _bj_dest=\"$FLOWAY_SETUP_TMPDIR/$_bj_asset\"\n  out_step 'jq not found on PATH; fetching the pinned jq-1.8.2 build'\n  if ! curl -fsSL --connect-timeout 10 --max-time 120 -o \"$_bj_dest\" \"$_bj_url\"; then\n    out_error \"failed to download jq from $_bj_url\"\n    rm -f \"$_bj_dest\"\n    return 1\n  fi\n  if command -v sha256sum >/dev/null 2>&1; then\n    _bj_actual=$(sha256sum \"$_bj_dest\" | awk '{ print $1 }')\n  elif command -v shasum >/dev/null 2>&1; then\n    _bj_actual=$(shasum -a 256 \"$_bj_dest\" | awk '{ print $1 }')\n  elif command -v openssl >/dev/null 2>&1; then\n    _bj_actual=$(openssl dgst -sha256 \"$_bj_dest\" | awk '{ print $NF }')\n  else\n    _bj_actual=\"\"\n  fi\n  if [ -z \"$_bj_actual\" ]; then\n    out_error 'no SHA-256 tool available to verify the jq download.'\n    rm -f \"$_bj_dest\"\n    return 1\n  fi\n  if [ \"$_bj_actual\" != \"$_bj_sha\" ]; then\n    out_error 'jq checksum mismatch; refusing to use the download.'\n    rm -f \"$_bj_dest\"\n    return 1\n  fi\n  if ! chmod 700 \"$_bj_dest\"; then\n    rm -f \"$_bj_dest\"\n    return 1\n  fi\n  JQ=\"$_bj_dest\"\n}\n\n# Resolve a usable jq: prefer PATH, else provision the pinned build. The\n# FLOWAY_INSTALLER_TEST_NO_JQ_DOWNLOAD hook lets the test harness assert the\n# fail-before-mutation path without reaching the network.\nensure_jq() {\n  if [ -n \"$JQ\" ]; then\n    return 0\n  fi\n  if command -v jq >/dev/null 2>&1; then\n    JQ=jq\n    return 0\n  fi\n  if [ -n \"${FLOWAY_INSTALLER_TEST_NO_JQ_DOWNLOAD:-}\" ]; then\n    return 1\n  fi\n  _bootstrap_jq\n}\n\n# Download an installer to the private working directory, refuse anything that\n# is not a shell script (region blocks and captive portals serve HTML in place\n# of the real installer), then execute it without sudo.\n_download_and_run_installer() {\n  _dri_url=$1\n  _dri_file=$(mktemp \"$FLOWAY_SETUP_TMPDIR/install.XXXXXX\") || return 1\n  if ! curl -fsSL --connect-timeout 10 --max-time 120 -o \"$_dri_file\" \"$_dri_url\"; then\n    out_error \"could not download the installer from $_dri_url\"\n    rm -f \"$_dri_file\"\n    return 1\n  fi\n  # Reject common HTML responses while allowing official shell content with or\n  # without a shebang (some installer CDNs prepend comments).\n  if awk '\n      NR <= 20 {\n        line = tolower($0)\n        if (line ~ /^[[:space:]]*(<!doctype[[:space:]]+html|<html([[:space:]>])|<head([[:space:]>])|<body([[:space:]>]))/) found = 1\n      }\n      END { exit found ? 0 : 1 }\n    ' \"$_dri_file\"; then\n    out_error 'the installer download was HTML, not an executable script (a login or region-block page?).'\n    rm -f \"$_dri_file\"\n    return 1\n  fi\n  if ! awk 'NF { found = 1 } END { exit found ? 0 : 1 }' \"$_dri_file\"; then\n    out_error 'the installer download was empty.'\n    rm -f \"$_dri_file\"\n    return 1\n  fi\n  _dri_timeout=${FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS:-120}\n  _run_with_timeout \"$_dri_timeout\" env -u FLOWAY_API_KEY bash \"$_dri_file\"\n  _dri_rc=$?\n  rm -f \"$_dri_file\"\n  return $_dri_rc\n}\n\n_discover_cli() {\n  _dc_name=$1\n  shift\n  DISCOVERED_BIN=$(command -v \"$_dc_name\" 2>/dev/null || true)\n  if [ -n \"$DISCOVERED_BIN\" ]; then\n    DISCOVERED_COUNT=1\n  else\n    DISCOVERED_COUNT=0\n  fi\n  for _dc_candidate in \"$@\"; do\n    [ -x \"$_dc_candidate\" ] || continue\n    [ \"$_dc_candidate\" = \"$DISCOVERED_BIN\" ] && continue\n    DISCOVERED_COUNT=$((DISCOVERED_COUNT + 1))\n    if [ -z \"$DISCOVERED_BIN\" ]; then\n      DISCOVERED_BIN=$_dc_candidate\n    fi\n  done\n}\n\n# Rollback retains a backup when restoration fails so manual recovery remains\n# possible. Callers keep separate transaction boundaries and aggregate failures.\n_restore_managed_file() {\n  _rmf_existed=$1\n  _rmf_backup=$2\n  _rmf_path=$3\n  _rmf_original_label=$4\n  _rmf_created_label=$5\n  if [ \"$_rmf_existed\" -eq 1 ]; then\n    if [ -n \"$_rmf_backup\" ] && [ -e \"$_rmf_backup\" ] && ! mv \"$_rmf_backup\" \"$_rmf_path\" 2>/dev/null; then\n      out_warn \"could not restore $_rmf_path from its backup; your original $_rmf_original_label is preserved at $_rmf_backup — restore it by hand.\"\n      return 1\n    fi\n  elif ! rm -f \"$_rmf_path\" 2>/dev/null; then\n    out_warn \"could not remove the $_rmf_created_label this run created at $_rmf_path — remove it by hand.\"\n    return 1\n  fi\n  return 0\n}\n\n# --- Claude Code ------------------------------------------------------------\n\n# Ref: https://docs.claude.com/en/docs/claude-code/troubleshoot-install\nclaude_ensure_installed() {\n  _discover_cli claude \\\n    \"$HOME/.local/bin/claude\" \\\n    \"$HOME/.claude/local/claude\" \\\n    \"$HOME/.bun/bin/claude\" \\\n    \"/opt/homebrew/bin/claude\" \\\n    \"/usr/local/bin/claude\"\n  CLAUDE_BIN=$DISCOVERED_BIN\n  if [ \"$DISCOVERED_COUNT\" -gt 1 ]; then\n    out_warn \"multiple Claude Code installations detected; using $CLAUDE_BIN\"\n  fi\n  if [ \"$DISCOVERED_COUNT\" -ge 1 ]; then\n    return 0\n  fi\n\n  out_step 'Claude Code CLI not found; installing the official build'\n  if [ -n \"${FLOWAY_INSTALLER_TEST_INSTALL_CLAUDE_SCRIPT:-}\" ]; then\n    _ic_timeout=${FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS:-120}\n    _run_with_timeout \"$_ic_timeout\" env -u FLOWAY_API_KEY bash \"$FLOWAY_INSTALLER_TEST_INSTALL_CLAUDE_SCRIPT\" || return 1\n  else\n    # Ref: https://docs.claude.com/en/docs/claude-code/setup (\"Native Install\").\n    _download_and_run_installer \"${FLOWAY_INSTALLER_TEST_CLAUDE_URL:-https://claude.ai/install.sh}\" || return 1\n  fi\n  hash -r 2>/dev/null || true\n  _discover_cli claude \\\n    \"$HOME/.local/bin/claude\" \\\n    \"$HOME/.claude/local/claude\" \\\n    \"$HOME/.bun/bin/claude\" \\\n    \"/opt/homebrew/bin/claude\" \\\n    \"/usr/local/bin/claude\"\n  CLAUDE_BIN=$DISCOVERED_BIN\n  [ \"$DISCOVERED_COUNT\" -ge 1 ]\n}\n\nclaude_rollback_settings() {\n  _restore_managed_file \\\n    \"${CLAUDE_SETTINGS_EXISTED:-0}\" \"${CLAUDE_SETTINGS_BACKUP:-}\" \"$CLAUDE_SETTINGS_PATH\" \\\n    \"file\" \"Claude settings\"\n}\n\n# Surgically merge the managed keys into the Claude settings file: validate the\n# existing document, back it up, construct and validate the replacement in the\n# same directory, then atomically rename it into place at mode 0600.\nclaude_write_settings() {\n  _cw_dir=\"${CLAUDE_CONFIG_DIR:-$HOME/.claude}\"\n  CLAUDE_SETTINGS_PATH=\"$_cw_dir/settings.json\"\n  CLAUDE_SETTINGS_BACKUP=\"\"\n  CLAUDE_SETTINGS_EXISTED=0\n\n  if ! mkdir -p \"$_cw_dir\"; then\n    out_error \"could not create $_cw_dir\"\n    return 1\n  fi\n\n  if [ -e \"$CLAUDE_SETTINGS_PATH\" ]; then\n    CLAUDE_SETTINGS_EXISTED=1\n    if ! \"$JQ\" '\n        if type != \"object\" then error(\"root is not a JSON object\")\n        elif (has(\"env\") and ((.env | type) != \"object\")) then error(\"env is not a JSON object\")\n        else . end\n      ' \"$CLAUDE_SETTINGS_PATH\" >/dev/null 2>&1; then\n      out_error \"$CLAUDE_SETTINGS_PATH is not valid Claude settings; leaving it untouched.\"\n      return 1\n    fi\n    _cw_base=$(cat \"$CLAUDE_SETTINGS_PATH\")\n    CLAUDE_SETTINGS_BACKUP=\"$CLAUDE_SETTINGS_PATH.floway-backup.$(date +%Y%m%d%H%M%S).$$\"\n    if ! cp \"$CLAUDE_SETTINGS_PATH\" \"$CLAUDE_SETTINGS_BACKUP\"; then\n      out_error \"could not back up $CLAUDE_SETTINGS_PATH\"\n      return 1\n    fi\n  else\n    _cw_base='{}'\n  fi\n\n  _cw_stage=\"$CLAUDE_SETTINGS_PATH.floway-stage.$$\"\n  if ! printf '%s' \"$_cw_base\" | FLOWAY_API_KEY=\"$FLOWAY_API_KEY\" \"$JQ\" \\\n      --arg baseUrl \"$FLOWAY_BASE_URL\" \\\n      --arg model \"$FLOWAY_CLAUDE_MODEL\" \\\n      --arg opus \"$FLOWAY_CLAUDE_DEFAULT_OPUS_MODEL\" \\\n      --arg sonnet \"$FLOWAY_CLAUDE_DEFAULT_SONNET_MODEL\" \\\n      --arg haiku \"$FLOWAY_CLAUDE_DEFAULT_HAIKU_MODEL\" \\\n      --arg discovery \"$FLOWAY_CLAUDE_MODEL_DISCOVERY\" \\\n      --arg effort \"$FLOWAY_CLAUDE_EFFORT_LEVEL\" \\\n      \"$CLAUDE_MERGE_PROGRAM\" > \"$_cw_stage\"; then\n    out_error 'failed to construct updated Claude settings.'\n    rm -f \"$_cw_stage\"\n    claude_rollback_settings\n    return 1\n  fi\n\n  if ! FLOWAY_API_KEY=\"$FLOWAY_API_KEY\" \"$JQ\" -e --arg baseUrl \"$FLOWAY_BASE_URL\" '\n      (type == \"object\")\n      and ((.env | type) == \"object\")\n      and (.env.ANTHROPIC_BASE_URL == $baseUrl)\n      and (.env.ANTHROPIC_AUTH_TOKEN == env.FLOWAY_API_KEY)\n    ' \"$_cw_stage\" >/dev/null 2>&1; then\n    out_error 'staged Claude settings failed validation.'\n    rm -f \"$_cw_stage\"\n    claude_rollback_settings\n    return 1\n  fi\n\n  if ! chmod 600 \"$_cw_stage\"; then\n    rm -f \"$_cw_stage\"\n    claude_rollback_settings\n    return 1\n  fi\n\n  if ! mv \"$_cw_stage\" \"$CLAUDE_SETTINGS_PATH\"; then\n    out_error \"could not replace $CLAUDE_SETTINGS_PATH\"\n    rm -f \"$_cw_stage\"\n    claude_rollback_settings\n    return 1\n  fi\n}\n\n# Confirm the gateway's authenticated model directory answers. No inference\n# request is issued. The key is passed through a mode-0600 curl config file so\n# it never reaches the process argument list.\nclaude_check_models() {\n  _cm_cfg=\"$FLOWAY_SETUP_TMPDIR/claude-curl.cfg\"\n  {\n    printf 'silent\\n'\n    printf 'show-error\\n'\n    printf 'fail\\n'\n    printf 'header = \"anthropic-version: 2023-06-01\"\\n'\n    printf 'header = \"Authorization: Bearer %s\"\\n' \"$FLOWAY_API_KEY\"\n    printf 'header = \"x-api-key: %s\"\\n' \"$FLOWAY_API_KEY\"\n  } > \"$_cm_cfg\"\n  chmod 600 \"$_cm_cfg\" 2>/dev/null || true\n  curl -K \"$_cm_cfg\" --connect-timeout 10 --max-time 30 -o /dev/null \"${FLOWAY_BASE_URL%/}/v1/models\"\n  _cm_rc=$?\n  rm -f \"$_cm_cfg\"\n  return $_cm_rc\n}\n\n# Verify the Claude configuration without inference: reparse the written\n# settings, print the raw CLI version, reach the authenticated model directory,\n# and run `claude doctor` when the subcommand exists. Doctor output is redacted\n# before it is surfaced.\nclaude_verify() {\n  if ! FLOWAY_API_KEY=\"$FLOWAY_API_KEY\" \"$JQ\" -e --arg baseUrl \"$FLOWAY_BASE_URL\" '\n      (type == \"object\")\n      and ((.env | type) == \"object\")\n      and (.env.ANTHROPIC_BASE_URL == $baseUrl)\n      and (.env.ANTHROPIC_AUTH_TOKEN == env.FLOWAY_API_KEY)\n    ' \"$CLAUDE_SETTINGS_PATH\" >/dev/null 2>&1; then\n    out_error 'the written Claude settings did not reparse as expected.'\n    return 1\n  fi\n\n  _cv_timeout=${FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS:-30}\n  _cv_version_file=\"$FLOWAY_SETUP_TMPDIR/claude-version.out\"\n  if _run_with_timeout \"$_cv_timeout\" \"$CLAUDE_BIN\" --version > \"$_cv_version_file\" 2>&1; then\n    _cv_version=$(cat \"$_cv_version_file\")\n  else\n    _cv_version_status=$?\n    if [ \"$_cv_version_status\" -eq 124 ]; then\n      out_error '`claude --version` timed out.'\n    else\n      out_error '`claude --version` failed.'\n    fi\n    return 1\n  fi\n  out_info \"Claude Code version: $_cv_version\"\n\n  if ! claude_check_models; then\n    out_error \"could not reach the authenticated model directory at ${FLOWAY_BASE_URL%/}/v1/models\"\n    return 1\n  fi\n  out_success 'reached the authenticated model directory (no inference issued).'\n\n  _cv_doctor_help=\"$FLOWAY_SETUP_TMPDIR/claude-doctor-help.out\"\n  if _run_with_timeout \"$_cv_timeout\" \"$CLAUDE_BIN\" doctor --help </dev/null > \"$_cv_doctor_help\" 2>&1; then\n    if _run_with_timeout \"$_cv_timeout\" \"$CLAUDE_BIN\" doctor </dev/null > \"$FLOWAY_SETUP_TMPDIR/claude-doctor.out\" 2>&1; then\n      out_success 'claude doctor reported no blocking issues.'\n    else\n      _cv_doctor_status=$?\n      if [ \"$_cv_doctor_status\" -eq 124 ]; then\n        out_error 'claude doctor timed out.'\n      else\n        out_error 'claude doctor reported a problem:'\n        out_captured < \"$FLOWAY_SETUP_TMPDIR/claude-doctor.out\"\n      fi\n      return 1\n    fi\n  else\n    _cv_help_status=$?\n    if [ \"$_cv_help_status\" -eq 124 ]; then\n      out_error 'claude doctor capability check timed out.'\n      return 1\n    fi\n    if grep -Eiq '(unknown|unrecognized|invalid|no such).*(command|subcommand).*doctor|doctor.*(unknown|unrecognized|invalid).*(command|subcommand)' \"$_cv_doctor_help\"; then\n      out_info 'this Claude Code build has no doctor command; skipping that check.'\n    else\n      out_error 'claude doctor capability check failed:'\n      out_captured < \"$_cv_doctor_help\"\n      return 1\n    fi\n  fi\n}\n\n# Configure Claude Code as one transactional unit. jq must resolve before any\n# mutation. Verification failure rolls back the settings write; a freshly\n# installed CLI is never uninstalled.\nconfigure_claude() {\n  out_phase 'Claude Code'\n  if ! ensure_jq; then\n    out_error 'jq is required to configure Claude Code but is unavailable and could not be provisioned for this platform. Install jq and re-run.'\n    return 1\n  fi\n  if ! claude_ensure_installed; then\n    out_error 'Claude Code CLI is unavailable and could not be installed.'\n    return 1\n  fi\n  if ! claude_write_settings; then\n    return 1\n  fi\n  if ! claude_verify; then\n    out_warn 'Claude Code verification failed; rolling back settings.'\n    claude_rollback_settings\n    return 1\n  fi\n  out_success 'Claude Code configured.'\n}\n\n# --- Codex ------------------------------------------------------------------\n\n# Ref: https://github.com/openai/codex/blob/main/scripts/install/install.sh\ncodex_ensure_installed() {\n  _discover_cli codex \\\n    \"$HOME/.local/bin/codex\" \\\n    \"/opt/homebrew/bin/codex\" \\\n    \"/usr/local/bin/codex\"\n  CODEX_BIN=$DISCOVERED_BIN\n  if [ \"$DISCOVERED_COUNT\" -gt 1 ]; then\n    out_warn \"multiple Codex installations detected; using $CODEX_BIN\"\n  fi\n  if [ \"$DISCOVERED_COUNT\" -ge 1 ]; then\n    return 0\n  fi\n\n  out_step 'Codex CLI not found; installing the official build'\n  if [ -n \"${FLOWAY_INSTALLER_TEST_INSTALL_CODEX_SCRIPT:-}\" ]; then\n    _icx_timeout=${FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS:-120}\n    _run_with_timeout \"$_icx_timeout\" env -u FLOWAY_API_KEY CODEX_NON_INTERACTIVE=true bash \"$FLOWAY_INSTALLER_TEST_INSTALL_CODEX_SCRIPT\" || return 1\n  else\n    # Ref: https://github.com/openai/codex README (\"curl -fsSL https://chatgpt.com/codex/install.sh | sh\").\n    CODEX_NON_INTERACTIVE=true _download_and_run_installer \"${FLOWAY_INSTALLER_TEST_CODEX_URL:-https://chatgpt.com/codex/install.sh}\" || return 1\n  fi\n  hash -r 2>/dev/null || true\n  _discover_cli codex \\\n    \"$HOME/.local/bin/codex\" \\\n    \"/opt/homebrew/bin/codex\" \\\n    \"/usr/local/bin/codex\"\n  CODEX_BIN=$DISCOVERED_BIN\n  [ \"$DISCOVERED_COUNT\" -ge 1 ]\n}\n\n# Back up the config and provider token before any mutation, recording the\n# absence of each so rollback can distinguish \"restore\" from \"remove\". The\n# token backup must be owner-only before the transaction can continue.\ncodex_backup_files() {\n  CODEX_CONFIG_EXISTED=0\n  CODEX_TOKEN_EXISTED=0\n  CODEX_CONFIG_BACKUP=\"\"\n  CODEX_TOKEN_BACKUP=\"\"\n  _cbf_stamp=$(date +%Y%m%d%H%M%S).$$\n  if [ -e \"$CODEX_CONFIG_PATH\" ]; then\n    CODEX_CONFIG_EXISTED=1\n    CODEX_CONFIG_BACKUP=\"$CODEX_CONFIG_PATH.floway-backup.$_cbf_stamp\"\n    if ! cp \"$CODEX_CONFIG_PATH\" \"$CODEX_CONFIG_BACKUP\"; then\n      out_error \"could not back up $CODEX_CONFIG_PATH\"\n      return 1\n    fi\n  fi\n  if [ -e \"$CODEX_TOKEN_PATH\" ]; then\n    CODEX_TOKEN_EXISTED=1\n    CODEX_TOKEN_BACKUP=\"$CODEX_TOKEN_PATH.floway-backup.$_cbf_stamp\"\n    if ! cp \"$CODEX_TOKEN_PATH\" \"$CODEX_TOKEN_BACKUP\"; then\n      out_error \"could not back up $CODEX_TOKEN_PATH\"\n      return 1\n    fi\n    if ! chmod 600 \"$CODEX_TOKEN_BACKUP\"; then\n      rm -f \"$CODEX_TOKEN_BACKUP\"\n      CODEX_TOKEN_BACKUP=\"\"\n      out_error \"could not protect the backup of $CODEX_TOKEN_PATH\"\n      return 1\n    fi\n  fi\n}\n\n# Both restores are attempted even when the first fails.\ncodex_rollback() {\n  _cxr_rc=0\n  _restore_managed_file \\\n    \"${CODEX_CONFIG_EXISTED:-0}\" \"${CODEX_CONFIG_BACKUP:-}\" \"$CODEX_CONFIG_PATH\" \\\n    \"file\" \"Codex config\" || _cxr_rc=1\n  _restore_managed_file \\\n    \"${CODEX_TOKEN_EXISTED:-0}\" \"${CODEX_TOKEN_BACKUP:-}\" \"$CODEX_TOKEN_PATH\" \\\n    \"provider token\" \"Codex provider token\" || _cxr_rc=1\n  return \"$_cxr_rc\"\n}\n\n# Terminate the app-server process group, giving a child whose stdin was just\n# closed a brief moment to exit on its own before escalating TERM then KILL. The\n# child is launched under job control so the whole descendant tree shares one\n# group. The natural-exit grace uses sub-second polling so a clean handshake\n# adds negligible latency.\n_codex_kill_group() {\n  _ckg_pid=$1\n  _ckg_n=0\n  while kill -0 \"$_ckg_pid\" 2>/dev/null && [ \"$_ckg_n\" -lt 5 ]; do\n    sleep 0.2\n    _ckg_n=$((_ckg_n + 1))\n  done\n  if kill -0 \"$_ckg_pid\" 2>/dev/null; then\n    kill -TERM -- \"-$_ckg_pid\" 2>/dev/null || kill -TERM \"$_ckg_pid\" 2>/dev/null || true\n    sleep 0.5\n    kill -KILL -- \"-$_ckg_pid\" 2>/dev/null || kill -KILL \"$_ckg_pid\" 2>/dev/null || true\n  fi\n  wait \"$_ckg_pid\" 2>/dev/null || true\n}\n\n# Read newline-delimited JSON-RPC from fd 4 until a response whose id matches\n# $1 arrives, demultiplexing unrelated notifications. Bounded by the absolute\n# CODEX_APPSERVER_DEADLINE. Returns 0 with the line in CODEX_APPSERVER_RESPONSE,\n# 124 on deadline, 1 on a premature stream EOF, 2 on a malformed (unparseable)\n# line, and 3 on a matching JSON-RPC error response.\n_codex_read_response() {\n  _crr_id=$1\n  while :; do\n    _crr_left=$(( CODEX_APPSERVER_DEADLINE - $(date +%s) ))\n    if [ \"$_crr_left\" -le 0 ]; then\n      return 124\n    fi\n    if IFS= read -r -t \"$_crr_left\" _crr_line <&4; then\n      [ -n \"$_crr_line\" ] || continue\n      _crr_kind=$(printf '%s\\n' \"$_crr_line\" | \"$JQ\" -r --argjson want \"$_crr_id\" '\n        if (.id == $want) then (if has(\"error\") then \"error\" elif has(\"result\") then \"result\" else \"pending\" end) else \"skip\" end\n      ' 2>/dev/null)\n      if [ -z \"$_crr_kind\" ]; then\n        return 2\n      fi\n      case \"$_crr_kind\" in\n        result) CODEX_APPSERVER_RESPONSE=$_crr_line; return 0 ;;\n        error) CODEX_APPSERVER_RESPONSE=$_crr_line; return 3 ;;\n        *) continue ;;\n      esac\n    else\n      _crr_rc=$?\n      if [ \"$_crr_rc\" -gt 128 ]; then\n        return 124\n      fi\n      return 1\n    fi\n  done\n}\n\n# Drive `codex app-server` over two private FIFOs: initialize -> initialized ->\n# config/batchWrite. stdin is kept open (fd 3) until the batch response arrives\n# on fd 4, so a server that answers after a delay still completes. The child\n# runs in its own process group for tree-wide termination; trap-invoked cleanup\n# removes the working directory. On success the raw batchWrite result JSON is the\n# only thing written to stdout (progress and errors go to stderr).\ncodex_app_server_batch_write() {\n  _cas_edits=$1\n  _cas_timeout=${FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS:-60}\n  _cas_dir=$(mktemp -d \"$FLOWAY_SETUP_TMPDIR/codex-appserver.XXXXXX\") || return 1\n  _cas_req=\"$_cas_dir/req\"\n  _cas_res=\"$_cas_dir/res\"\n  if ! mkfifo \"$_cas_req\" \"$_cas_res\"; then\n    rm -rf \"$_cas_dir\"\n    return 1\n  fi\n\n  set -m\n  \"$CODEX_BIN\" app-server --listen stdio:// <\"$_cas_req\" >\"$_cas_res\" 2>\"$_cas_dir/stderr\" &\n  _cas_pid=$!\n  set +m\n\n  # Open the write end of req first (this unblocks the child's stdin open), then\n  # the read end of res. This ordering is what keeps a FIFO pair from deadlocking.\n  exec 3>\"$_cas_req\"\n  exec 4<\"$_cas_res\"\n\n  CODEX_APPSERVER_DEADLINE=$(( $(date +%s) + _cas_timeout ))\n  CODEX_APPSERVER_RESPONSE=\"\"\n  _cas_status=0\n\n  _cas_init=$(\"$JQ\" -cn '{jsonrpc:\"2.0\",id:1,method:\"initialize\",params:{clientInfo:{name:\"floway-setup\",title:null,version:\"1\"},capabilities:null}}')\n  printf '%s\\n' \"$_cas_init\" >&3 2>/dev/null || _cas_status=1\n  if [ \"$_cas_status\" -eq 0 ]; then\n    _codex_read_response 1\n    _cas_status=$?\n  fi\n  if [ \"$_cas_status\" -eq 0 ]; then\n    printf '%s\\n' '{\"jsonrpc\":\"2.0\",\"method\":\"initialized\"}' >&3 2>/dev/null || _cas_status=1\n  fi\n  if [ \"$_cas_status\" -eq 0 ]; then\n    _cas_batch=$(\"$JQ\" -cn --argjson edits \"$_cas_edits\" '{jsonrpc:\"2.0\",id:2,method:\"config/batchWrite\",params:{edits:$edits}}')\n    printf '%s\\n' \"$_cas_batch\" >&3 2>/dev/null || _cas_status=1\n  fi\n  _cas_result=\"\"\n  if [ \"$_cas_status\" -eq 0 ]; then\n    _codex_read_response 2\n    _cas_status=$?\n    _cas_result=$CODEX_APPSERVER_RESPONSE\n  fi\n\n  exec 3>&- 2>/dev/null || true\n  exec 4<&- 2>/dev/null || true\n  _codex_kill_group \"$_cas_pid\"\n  rm -rf \"$_cas_dir\"\n\n  if [ \"$_cas_status\" -ne 0 ]; then\n    return \"$_cas_status\"\n  fi\n  printf '%s' \"$_cas_result\"\n}\n\n# Build the base-config edit batch and write it through the app-server. Model\n# and effort are opaque, forwarded verbatim, and cleared with JSON null when\n# unset. A batch status of `ok` or `okOverridden` confirms the intended base\n# config; `okOverridden` is reported with its non-secret layer metadata.\ncodex_write_config() {\n  _cwc_base=\"${FLOWAY_BASE_URL%/}/azure-api.codex\"\n  # Command auth opts a provider into online model refresh. The actor marker\n  # enables Codex's client-owned search and image extensions for this provider.\n  # https://github.com/openai/codex/blob/1bbdb32789e1f79932df44941236ea3658f6e965/codex-rs/models-manager/src/manager.rs#L413-L415\n  # https://github.com/openai/codex/blob/1bbdb32789e1f79932df44941236ea3658f6e965/codex-rs/model-provider-info/src/lib.rs#L396-L408\n  _cwc_edits=$(\"$JQ\" -cn \\\n    --arg base \"$_cwc_base\" \\\n    --arg model \"$FLOWAY_CODEX_MODEL\" \\\n    --arg effort \"$FLOWAY_CODEX_REASONING_EFFORT\" '\n    [\n      {keyPath:\"model_provider\",mergeStrategy:\"replace\",value:\"floway\"},\n      {keyPath:\"model_providers.floway.name\",mergeStrategy:\"replace\",value:\"Floway\"},\n      {keyPath:\"model_providers.floway.base_url\",mergeStrategy:\"replace\",value:$base},\n      {keyPath:\"model_providers.floway.auth\",mergeStrategy:\"replace\",value:{command:\"sh\",args:[\"-c\",\"cat \\\"${CODEX_HOME:-$HOME/.codex}/floway-token\\\"\"]}},\n      {keyPath:\"model_providers.floway.wire_api\",mergeStrategy:\"replace\",value:\"responses\"},\n      {keyPath:\"model_providers.floway.supports_websockets\",mergeStrategy:\"replace\",value:true},\n      {keyPath:\"model_providers.floway.http_headers\",mergeStrategy:\"replace\",value:{\"x-openai-actor-authorization\":\"1\"}},\n      {keyPath:\"features.apps\",mergeStrategy:\"replace\",value:false},\n      {keyPath:\"features.standalone_web_search\",mergeStrategy:\"replace\",value:true},\n      {keyPath:\"model\",mergeStrategy:\"replace\",value:(if $model == \"\" then null else $model end)},\n      {keyPath:\"model_reasoning_effort\",mergeStrategy:\"replace\",value:(if $effort == \"\" then null else $effort end)}\n    ]') || {\n    out_error 'could not build the Codex configuration edits.'\n    return 1\n  }\n\n  _cwc_result=$(codex_app_server_batch_write \"$_cwc_edits\")\n  _cwc_rc=$?\n  if [ \"$_cwc_rc\" -ne 0 ]; then\n    case \"$_cwc_rc\" in\n      124) out_error 'the Codex app-server timed out before confirming the configuration.' ;;\n      3) out_error 'the Codex app-server reported an error writing the configuration.' ;;\n      2) out_error 'the Codex app-server returned a malformed response.' ;;\n      1) out_error 'the Codex app-server exited before confirming the configuration.' ;;\n      *) out_error 'the Codex app-server configuration failed.' ;;\n    esac\n    return 1\n  fi\n\n  _cwc_status=$(printf '%s' \"$_cwc_result\" | \"$JQ\" -r '.result.status // empty' 2>/dev/null)\n  case \"$_cwc_status\" in\n    ok)\n      out_success 'Codex base configuration written.'\n      ;;\n    okOverridden)\n      _cwc_msg=$(printf '%s' \"$_cwc_result\" | \"$JQ\" -r '.result.overriddenMetadata.message // \"an override layer applies\"' 2>/dev/null)\n      _cwc_layer=$(printf '%s' \"$_cwc_result\" | \"$JQ\" -r '.result.overriddenMetadata.overridingLayer.name.type // \"unknown\"' 2>/dev/null)\n      out_warn \"Codex base configuration written, but a higher-precedence layer overrides it ($_cwc_msg; layer: $_cwc_layer).\"\n      ;;\n    *)\n      out_error \"the Codex app-server did not confirm the configuration (status: ${_cwc_status:-none}).\"\n      return 1\n      ;;\n  esac\n}\n\n# Store the Floway API key as a provider-scoped command-auth token. The private\n# stage is validated byte-for-byte, then atomically renamed. auth.json is an\n# account-owned Codex file and is never read or changed here.\ncodex_stage_token() {\n  _cst_stage=\"$CODEX_TOKEN_PATH.floway-stage.$$\"\n  if ! (umask 077 && : > \"$_cst_stage\"); then\n    out_error 'could not create the Codex provider-token stage.'\n    return 1\n  fi\n  if ! printf '%s' \"$FLOWAY_API_KEY\" > \"$_cst_stage\"; then\n    out_error 'could not write the Codex provider-token stage.'\n    rm -f \"$_cst_stage\"\n    return 1\n  fi\n  if ! cmp -s \"$_cst_stage\" <(printf '%s' \"$FLOWAY_API_KEY\"); then\n    out_error 'staged Codex provider token failed validation.'\n    rm -f \"$_cst_stage\"\n    return 1\n  fi\n  if ! chmod 600 \"$_cst_stage\"; then\n    rm -f \"$_cst_stage\"\n    return 1\n  fi\n  if ! mv \"$_cst_stage\" \"$CODEX_TOKEN_PATH\"; then\n    out_error \"could not replace $CODEX_TOKEN_PATH\"\n    rm -f \"$_cst_stage\"\n    return 1\n  fi\n}\n\n# Confirm the gateway's authenticated Codex model directory answers. No inference\n# request is issued. When a model was selected, confirm it is present in the\n# returned catalog. The key is passed through a mode-0600 curl config file so it\n# never reaches the process argument list.\ncodex_check_models() {\n  _ccm_base=\"${FLOWAY_BASE_URL%/}/azure-api.codex\"\n  _ccm_cfg=\"$FLOWAY_SETUP_TMPDIR/codex-curl.cfg\"\n  {\n    printf 'silent\\n'\n    printf 'show-error\\n'\n    printf 'fail\\n'\n    printf 'header = \"Authorization: Bearer %s\"\\n' \"$FLOWAY_API_KEY\"\n  } > \"$_ccm_cfg\"\n  chmod 600 \"$_ccm_cfg\" 2>/dev/null || true\n  _ccm_body=\"$FLOWAY_SETUP_TMPDIR/codex-models.json\"\n  curl -K \"$_ccm_cfg\" --connect-timeout 10 --max-time 30 -o \"$_ccm_body\" \"$_ccm_base/models\"\n  _ccm_rc=$?\n  rm -f \"$_ccm_cfg\"\n  if [ \"$_ccm_rc\" -ne 0 ]; then\n    rm -f \"$_ccm_body\"\n    return 1\n  fi\n  if [ -n \"$FLOWAY_CODEX_MODEL\" ]; then\n    if ! \"$JQ\" -e --arg m \"$FLOWAY_CODEX_MODEL\" 'any(.models[]?; .slug == $m)' \"$_ccm_body\" >/dev/null 2>&1; then\n      out_error \"the selected Codex model $FLOWAY_CODEX_MODEL is not in the gateway catalog.\"\n      rm -f \"$_ccm_body\"\n      return 1\n    fi\n  fi\n  rm -f \"$_ccm_body\"\n}\n\n# Verify Codex without inference: compare the provider token without printing\n# it, print the raw CLI version, and reach the authenticated model directory\n# (confirming the selected model when one is set).\ncodex_verify() {\n  if ! cmp -s \"$CODEX_TOKEN_PATH\" <(printf '%s' \"$FLOWAY_API_KEY\"); then\n    out_error 'the written Codex provider token did not reparse as expected.'\n    return 1\n  fi\n\n  _cv_timeout=${FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS:-30}\n  _cv_version_file=\"$FLOWAY_SETUP_TMPDIR/codex-version.out\"\n  if _run_with_timeout \"$_cv_timeout\" \"$CODEX_BIN\" --version > \"$_cv_version_file\" 2>&1; then\n    out_info \"Codex version: $(cat \"$_cv_version_file\")\"\n  else\n    _cv_version_status=$?\n    if [ \"$_cv_version_status\" -eq 124 ]; then\n      out_error '`codex --version` timed out.'\n    else\n      out_error '`codex --version` failed.'\n    fi\n    return 1\n  fi\n\n  if ! codex_check_models; then\n    out_error \"could not reach the authenticated Codex model directory at ${FLOWAY_BASE_URL%/}/azure-api.codex/models\"\n    return 1\n  fi\n  out_success 'reached the authenticated Codex model directory (no inference issued).'\n}\n\n# Configure Codex as one transactional unit. jq must resolve before any\n# mutation. The config and provider token are backed up first; a write or\n# verification failure restores both (or removes newly created files). A\n# freshly installed CLI is never uninstalled.\nconfigure_codex() {\n  out_phase 'Codex'\n  if ! ensure_jq; then\n    out_error 'jq is required to configure Codex but is unavailable and could not be provisioned for this platform. Install jq and re-run.'\n    return 1\n  fi\n  if ! codex_ensure_installed; then\n    out_error 'Codex CLI is unavailable and could not be installed.'\n    return 1\n  fi\n  CODEX_HOME_DIR=\"${CODEX_HOME:-$HOME/.codex}\"\n  CODEX_CONFIG_PATH=\"$CODEX_HOME_DIR/config.toml\"\n  CODEX_TOKEN_PATH=\"$CODEX_HOME_DIR/floway-token\"\n  if ! mkdir -p \"$CODEX_HOME_DIR\"; then\n    out_error \"could not create $CODEX_HOME_DIR\"\n    return 1\n  fi\n  if ! codex_backup_files; then\n    return 1\n  fi\n  if ! codex_stage_token; then\n    out_warn 'Codex provider-token staging failed; rolling back configuration and token.'\n    codex_rollback\n    return 1\n  fi\n  if ! codex_write_config; then\n    out_warn 'Codex configuration failed; rolling back configuration and token.'\n    codex_rollback\n    return 1\n  fi\n  if ! codex_verify; then\n    out_warn 'Codex verification failed; rolling back configuration and token.'\n    codex_rollback\n    return 1\n  fi\n  out_success 'Codex configured.'\n}\n\n# --- run --------------------------------------------------------------------\n\nFLOWAY_SETUP_TMPDIR=$(mktemp -d \"${TMPDIR:-/tmp}/floway-setup.XXXXXX\") || {\n  out_fatal 'could not create a private working directory.'\n  exit 1\n}\nchmod 700 \"$FLOWAY_SETUP_TMPDIR\" 2>/dev/null || true\n\nCLAUDE_RESULT=skipped\nCODEX_RESULT=skipped\nOVERALL=0\n\nif [ -n \"$FLOWAY_INSTALL_CLAUDE\" ]; then\n  if configure_claude; then\n    CLAUDE_RESULT=configured\n  else\n    CLAUDE_RESULT=failed\n    OVERALL=1\n  fi\nfi\n\nif [ -n \"$FLOWAY_INSTALL_CODEX\" ]; then\n  if configure_codex; then\n    CODEX_RESULT=configured\n  else\n    CODEX_RESULT=failed\n    OVERALL=1\n  fi\nfi\n\nout_phase 'Summary'\nout_summary_entry 'Claude Code' \"$CLAUDE_RESULT\"\nout_summary_entry 'Codex' \"$CODEX_RESULT\"\n\nexit \"$OVERALL\"\n";

export const SETUP_PS1_BODY = "# Floway agent setup installer (PowerShell). The gateway prepends the\n# language-native assignment prefix before this fixed body.\n#\n# Each selected agent runs as an independent transaction so one failure does not\n# skip or roll back the other.\n\n$ErrorActionPreference = 'Stop'\n# Keep native (non-cmdlet) command failures from auto-throwing on PowerShell\n# 7.3+, so explicit $LASTEXITCODE checks stay authoritative across versions.\n$PSNativeCommandUseErrorActionPreference = $false\n\n# The server prefix uses ordinary variables, but defensively remove identically\n# named ambient environment variables so installers and CLI subprocesses cannot\n# inherit the API key.\nRemove-Item Env:FLOWAY_API_KEY -ErrorAction SilentlyContinue\nRemove-Item Env:FlowayApiKey -ErrorAction SilentlyContinue\n\n# --- output layer -----------------------------------------------------------\n#\n# Structure is carried by a compact box-line tree, identical in text to the Bash\n# installer: a blank line then `┌─ <name>` opens a phase, `│  ` continues its\n# body, `│  · ` marks a step, and the closing Summary phase lists each agent as\n# `<label>  [state]`. Informational, progress, and success lines go to stdout;\n# warnings, errors, rollback notices, and captured tool output go to stderr.\n#\n# stdout color rides the host: `Write-Host -ForegroundColor` colors an\n# interactive console yet writes no escape sequences when redirected/captured,\n# so it is the correct stdout mechanism on both Windows PowerShell 5.1 and\n# PowerShell 7. stderr goes through [Console]::Error, colored with ANSI only for\n# an interactive error stream with NO_COLOR unset — a redirected capture stays\n# escape-free. UTF-8 output makes the box-drawing glyphs render on 5.1 too.\ntry { [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false) } catch { }\n$script:FlowayNoColor = [bool]$env:NO_COLOR\n$script:FlowayForceColor = [bool]$env:FLOWAY_INSTALLER_TEST_FORCE_COLOR\n$script:FlowayErrColor = (-not [Console]::IsErrorRedirected) -and (-not $script:FlowayNoColor)\n$script:FlowayEsc = [char]27\n\nfunction Write-FlowayHostLine {\n  param([string]$Text, [System.ConsoleColor]$Color, [switch]$Plain)\n  if ($Plain -or $script:FlowayNoColor) { Write-Host $Text } else { Write-Host $Text -ForegroundColor $Color }\n}\n\n# Console.ForegroundColor works in Windows PowerShell 5.1 without requiring VT\n# mode and still writes the text to stderr. The forced-color branch is test-only:\n# redirected streams cannot expose host color, so it emits ANSI for assertions.\nfunction Write-FlowayErrLine {\n  param([string]$Text, [System.ConsoleColor]$Color, [string]$TestAnsiCode)\n  if ($script:FlowayErrColor) {\n    $previous = [Console]::ForegroundColor\n    try { [Console]::ForegroundColor = $Color; [Console]::Error.WriteLine($Text) }\n    finally { [Console]::ForegroundColor = $previous }\n  } elseif ($script:FlowayForceColor -and (-not $script:FlowayNoColor)) {\n    [Console]::Error.WriteLine(\"$($script:FlowayEsc)[${TestAnsiCode}m$Text$($script:FlowayEsc)[0m\")\n  } else {\n    [Console]::Error.WriteLine($Text)\n  }\n}\n\nfunction Write-FlowayTitle { Write-FlowayHostLine 'Floway agent setup' Cyan }\nfunction Write-FlowayPhase { param([string]$Name) Write-Host ''; Write-FlowayHostLine \"┌─ $Name\" Cyan }\nfunction Write-FlowayStep { param([string]$Text) Write-FlowayHostLine \"│  · $Text\" DarkCyan }\nfunction Write-FlowayInfo { param([string]$Text) Write-FlowayHostLine \"│  $Text\" -Plain }\nfunction Write-FlowaySuccess { param([string]$Text) Write-FlowayHostLine \"│  $Text\" Green }\nfunction Write-FlowayWarn { param([string]$Text) Write-FlowayErrLine \"│  $Text\" Yellow '93' }\nfunction Write-FlowayError { param([string]$Text) Write-FlowayErrLine \"│  $Text\" Red '91' }\n# A fatal line raised before any phase is open carries no spine.\nfunction Write-FlowayFatal { param([string]$Text) Write-FlowayErrLine $Text Red '91' }\n\n# Re-emit captured official-tool output as a de-emphasized, redacted, spined\n# block on stderr so it never masquerades as a Floway line.\nfunction Write-FlowayCaptured {\n  param([string]$Text)\n  $redacted = (Protect-FlowaySecret $Text).TrimEnd()\n  if ($redacted.Length -eq 0) { return }\n  foreach ($line in $redacted -split \"`r?`n\") { Write-FlowayErrLine \"│    $line\" DarkGray '90' }\n}\n\nfunction Write-FlowaySummaryEntry {\n  param([string]$Label, [string]$State)\n  $color = switch ($State) { 'configured' { 'Green' } 'failed' { 'Red' } default { 'DarkGray' } }\n  Write-FlowayHostLine \"│  $Label  [$State]\" $color\n}\n\n# Report a primary error to stderr and unwind. The agent boundary recognizes the\n# 'floway-handled' marker as already reported, so no line is ever duplicated.\nfunction Stop-FlowaySetup { param([string]$Message) Write-FlowayError $Message; throw 'floway-handled' }\n\nWrite-FlowayTitle\n\n# The wrapping command supplies $FlowayBaseUrl as an in-process variable.\n# Validate it before mutation; installer and CLI subprocesses never inherit it.\nif ([string]::IsNullOrWhiteSpace($FlowayBaseUrl)) {\n  Write-FlowayFatal \"`$FlowayBaseUrl must be set to this gateway origin (e.g. https://gateway.example).\"\n  exit 1\n}\nif ($FlowayBaseUrl -notmatch '^https?://.+') {\n  Write-FlowayFatal \"`$FlowayBaseUrl must be an http(s) origin, got $FlowayBaseUrl\"\n  exit 1\n}\n\n# --- common helpers ---------------------------------------------------------\n\nfunction Set-FlowayProp {\n  param($Target, [string]$Name, $Value)\n  if ($Target.PSObject.Properties.Name -contains $Name) { $Target.$Name = $Value }\n  else { $Target | Add-Member -NotePropertyName $Name -NotePropertyValue $Value }\n}\n\nfunction Remove-FlowayProp {\n  param($Target, [string]$Name)\n  if ($Target.PSObject.Properties.Name -contains $Name) { $Target.PSObject.Properties.Remove($Name) }\n}\n\n# A null optional value means \"remove this managed key\"; any other value is set.\nfunction Set-FlowayOptionalProp {\n  param($Target, [string]$Name, $Value)\n  if ($null -eq $Value) { Remove-FlowayProp $Target $Name } else { Set-FlowayProp $Target $Name $Value }\n}\n\n# Redact every occurrence of the API key from text before it is surfaced.\nfunction Protect-FlowaySecret {\n  param([string]$Text)\n  return ($Text -replace [regex]::Escape($FlowayApiKey), '***')\n}\n\n# Restrict a file to the current user: chmod 0600 on Unix, an inheritance-free\n# owner-only ACL on Windows.\nfunction Protect-FlowayFile {\n  param([string]$Path)\n  if (($PSVersionTable.PSVersion.Major -ge 6) -and (-not $IsWindows)) {\n    & chmod 600 $Path\n    if ($LASTEXITCODE -ne 0) { Stop-FlowaySetup \"could not restrict $Path to owner-only access.\" }\n    return\n  }\n  $acl = New-Object System.Security.AccessControl.FileSecurity\n  $identity = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name\n  $rule = New-Object System.Security.AccessControl.FileSystemAccessRule($identity, 'FullControl', 'Allow')\n  $acl.SetAccessRuleProtection($true, $false)\n  $acl.AddAccessRule($rule)\n  Set-Acl -Path $Path -AclObject $acl\n}\n\n# Terminate a process and its descendants. PowerShell 7's runtime exposes the\n# tree-aware Kill(bool) overload; Windows PowerShell 5.1 uses taskkill /T.\nfunction Stop-FlowayProcessTree {\n  param([System.Diagnostics.Process]$Process)\n  $runningOnWindows = ($PSVersionTable.PSVersion.Major -lt 6) -or $IsWindows\n  if ($runningOnWindows) {\n    & taskkill.exe /PID $Process.Id /T /F *> $null\n    if ($LASTEXITCODE -ne 0 -and (-not $Process.HasExited)) {\n      Stop-FlowaySetup \"taskkill could not terminate process tree $($Process.Id).\"\n    }\n    return\n  }\n  try {\n    # .NET used by PowerShell 7 supports tree-aware termination on Unix.\n    $Process.Kill($true)\n  } catch {\n    if (-not $Process.HasExited) { Stop-FlowaySetup \"could not terminate process tree $($Process.Id).\" }\n  }\n}\n\n# Execute a downloaded PowerShell installer in a fresh interpreter. The script\n# travels through stdin, while the API key exists only as a variable in this\n# parent process and its identically named environment variables were removed.\n# The official installer therefore cannot read the credential.\nfunction Invoke-FlowayPowerShellBody {\n  param([string]$Body, [int]$TimeoutSeconds, [switch]$BypassExecutionPolicy)\n  $startInfo = New-Object System.Diagnostics.ProcessStartInfo\n  $startInfo.FileName = [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName\n  $executionPolicy = if ($BypassExecutionPolicy) { '-ExecutionPolicy Bypass ' } else { '' }\n  $startInfo.Arguments = \"-NoProfile -NonInteractive ${executionPolicy}-Command -\"\n  $startInfo.UseShellExecute = $false\n  $startInfo.CreateNoWindow = $true\n  $startInfo.RedirectStandardInput = $true\n  $startInfo.RedirectStandardOutput = $true\n  $startInfo.RedirectStandardError = $true\n  $process = New-Object System.Diagnostics.Process\n  $process.StartInfo = $startInfo\n  if (-not $process.Start()) { Stop-FlowaySetup \"failed to start the installer interpreter.\" }\n  $stdoutTask = $process.StandardOutput.ReadToEndAsync()\n  $stderrTask = $process.StandardError.ReadToEndAsync()\n  $process.StandardInput.Write($Body)\n  $process.StandardInput.WriteLine()\n  $process.StandardInput.Close()\n  if (-not $process.WaitForExit($TimeoutSeconds * 1000)) {\n    Stop-FlowayProcessTree $process\n    $process.WaitForExit()\n    Stop-FlowaySetup \"the installer timed out after $TimeoutSeconds seconds.\"\n  }\n  $stdout = $stdoutTask.GetAwaiter().GetResult()\n  $stderr = $stderrTask.GetAwaiter().GetResult()\n  if ($stdout) { Write-FlowayCaptured $stdout.TrimEnd() }\n  if ($stderr) { Write-FlowayCaptured $stderr.TrimEnd() }\n  if ($process.ExitCode -ne 0) { Stop-FlowaySetup \"the installer exited with status $($process.ExitCode).\" }\n}\n\n# Download an installer, refuse anything that is not a script (region blocks and\n# captive portals serve HTML in place of the installer), then run it.\nfunction Invoke-FlowayRemoteInstaller {\n  param([string]$Uri, [switch]$BypassExecutionPolicy)\n  $response = Invoke-WebRequest -Uri $Uri -UseBasicParsing -TimeoutSec 60\n  $body = [string]$response.Content\n  $contentType = [string]$response.Headers['Content-Type']\n  $looksLikeHtml = $contentType -match '(?i)^text/html(?:;|$)' -or $body -match '(?is)^\\s*(?:<!doctype\\s+html|<html(?:\\s|>))'\n  if ([string]::IsNullOrWhiteSpace($body) -or $looksLikeHtml) {\n    Stop-FlowaySetup \"the installer download was HTML or empty, not an executable script (a login or region-block page?).\"\n  }\n  $timeoutSeconds = if ($env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS) { [int]$env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS } else { 120 }\n  Invoke-FlowayPowerShellBody -Body $body -TimeoutSeconds $timeoutSeconds -BypassExecutionPolicy:$BypassExecutionPolicy\n}\n\nfunction Get-FlowayCliExe {\n  param([string]$Name, [string]$Label, [string[]]$Candidates)\n  $found = New-Object System.Collections.Generic.List[string]\n  $command = Get-Command $Name -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1\n  if ($command) { $found.Add($command.Source) }\n  foreach ($candidate in $Candidates) {\n    if ((Test-Path -LiteralPath $candidate) -and (-not $found.Contains($candidate))) { $found.Add($candidate) }\n  }\n  if ($found.Count -eq 0) { return $null }\n  if ($found.Count -gt 1) { Write-FlowayWarn \"multiple $Label installations detected; using $($found[0])\" }\n  return $found[0]\n}\n\n# Rollback retains a backup when restoration fails so manual recovery remains\n# possible, warning with the preserved path and the action to take — matching\n# the Bash installer. The FLOWAY_INSTALLER_TEST_FAIL_RESTORE hook, read from the\n# ambient environment and never emitted by the gateway, forces the restore\n# rename to fail so the harness can assert that guidance.\nfunction Restore-FlowayManagedFile {\n  param([bool]$Existed, [string]$Backup, [string]$Path, [string]$OriginalLabel, [string]$CreatedLabel)\n  if ($Existed) {\n    if ($Backup -and (Test-Path -LiteralPath $Backup)) {\n      try {\n        if ($env:FLOWAY_INSTALLER_TEST_FAIL_RESTORE) { throw 'test-injected restore failure' }\n        # Secret-bearing backups were already owner-only before any mutation.\n        # Moving one back preserves that protection without a second operation\n        # that could fail after the backup path has been consumed.\n        Move-Item -LiteralPath $Backup -Destination $Path -Force\n      } catch {\n        Write-FlowayWarn \"could not restore $Path from its backup; your original $OriginalLabel is preserved at $Backup — restore it by hand.\"\n      }\n    }\n  } elseif (Test-Path -LiteralPath $Path) {\n    try {\n      Remove-Item -LiteralPath $Path -Force\n    } catch {\n      Write-FlowayWarn \"could not remove the $CreatedLabel this run created at $Path — remove it by hand.\"\n    }\n  }\n}\n\n# --- Claude Code ------------------------------------------------------------\n\n# Install the official user-local Claude Code build. The\n# FLOWAY_INSTALLER_TEST_INSTALL_CLAUDE_SCRIPT hook — read from the ambient\n# environment, never emitted by the gateway — substitutes a fake installer\n# under test.\nfunction Install-FlowayClaude {\n  if ($env:FLOWAY_INSTALLER_TEST_INSTALL_CLAUDE_SCRIPT) {\n    $timeoutSeconds = if ($env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS) { [int]$env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS } else { 120 }\n    $installer = Invoke-FlowayProcess -Exe $env:FLOWAY_INSTALLER_TEST_INSTALL_CLAUDE_SCRIPT -Arguments @() -TimeoutSeconds $timeoutSeconds\n    if ($installer.ExitCode -ne 0) { Stop-FlowaySetup \"the test installer hook failed.\" }\n    return\n  }\n  # Ref: https://docs.claude.com/en/docs/claude-code/setup (\"Native Install\").\n  $installerUri = if ($env:FLOWAY_INSTALLER_TEST_CLAUDE_URL) { $env:FLOWAY_INSTALLER_TEST_CLAUDE_URL } else { 'https://claude.ai/install.ps1' }\n  Invoke-FlowayRemoteInstaller -Uri $installerUri\n}\n\nfunction Restore-FlowayClaudeSettings {\n  Restore-FlowayManagedFile -Existed $script:ClaudeSettingsExisted -Backup $script:ClaudeSettingsBackup -Path $script:ClaudeSettingsPath -OriginalLabel 'file' -CreatedLabel 'Claude settings'\n}\n\n# Surgically merge the managed keys into the Claude settings file: validate the\n# existing document, back it up, construct and validate the replacement in the\n# same directory, then atomically rename it into place with owner-only access.\nfunction Write-FlowayClaudeSettings {\n  $configDir = if ($env:CLAUDE_CONFIG_DIR) { $env:CLAUDE_CONFIG_DIR } else { Join-Path $HOME '.claude' }\n  $script:ClaudeSettingsPath = Join-Path $configDir 'settings.json'\n  $script:ClaudeSettingsBackup = $null\n  $script:ClaudeSettingsExisted = $false\n  if (-not (Test-Path -LiteralPath $configDir)) {\n    New-Item -ItemType Directory -Path $configDir -Force | Out-Null\n  }\n\n  $document = $null\n  if (Test-Path -LiteralPath $script:ClaudeSettingsPath) {\n    $script:ClaudeSettingsExisted = $true\n    $raw = Get-Content -Raw -LiteralPath $script:ClaudeSettingsPath\n    try { $document = $raw | ConvertFrom-Json } catch { Stop-FlowaySetup \"$($script:ClaudeSettingsPath) is not valid JSON; leaving it untouched.\" }\n    if ($document -isnot [System.Management.Automation.PSCustomObject]) { Stop-FlowaySetup \"existing Claude settings root is not a JSON object.\" }\n    if (($document.PSObject.Properties.Name -contains 'env') -and ($document.env -isnot [System.Management.Automation.PSCustomObject])) {\n      Stop-FlowaySetup \"existing Claude settings env is not a JSON object.\"\n    }\n    # DateTimeOffset.ToUnixTimeMilliseconds is unavailable on the .NET\n    # Framework version bundled with the Windows PowerShell 5.1 baseline.\n    $stamp = [long]([DateTimeOffset]::UtcNow - [DateTimeOffset]'1970-01-01T00:00:00Z').TotalMilliseconds\n    $script:ClaudeSettingsBackup = \"$($script:ClaudeSettingsPath).floway-backup.$stamp.$PID\"\n    try {\n      Copy-Item -LiteralPath $script:ClaudeSettingsPath -Destination $script:ClaudeSettingsBackup\n      Protect-FlowayFile $script:ClaudeSettingsBackup\n    } catch {\n      if (Test-Path -LiteralPath $script:ClaudeSettingsBackup) {\n        Remove-Item -LiteralPath $script:ClaudeSettingsBackup -Force\n      }\n      $script:ClaudeSettingsBackup = $null\n      throw\n    }\n  } else {\n    $document = [PSCustomObject]@{}\n  }\n\n  if ($document.PSObject.Properties.Name -notcontains 'env') {\n    $document | Add-Member -NotePropertyName env -NotePropertyValue ([PSCustomObject]@{})\n  }\n  Set-FlowayProp $document.env 'ANTHROPIC_BASE_URL' $FlowayBaseUrl\n  Set-FlowayProp $document.env 'ANTHROPIC_AUTH_TOKEN' $FlowayApiKey\n  Set-FlowayOptionalProp $document.env 'ANTHROPIC_MODEL' $FlowayClaudeModel\n  Set-FlowayOptionalProp $document.env 'ANTHROPIC_DEFAULT_OPUS_MODEL' $FlowayClaudeDefaultOpusModel\n  Set-FlowayOptionalProp $document.env 'ANTHROPIC_DEFAULT_SONNET_MODEL' $FlowayClaudeDefaultSonnetModel\n  Set-FlowayOptionalProp $document.env 'ANTHROPIC_DEFAULT_HAIKU_MODEL' $FlowayClaudeDefaultHaikuModel\n  if ($FlowayClaudeModelDiscovery) { Set-FlowayProp $document.env 'CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY' '1' }\n  else { Remove-FlowayProp $document.env 'CLAUDE_CODE_ENABLE_GATEWAY_MODEL_DISCOVERY' }\n  Set-FlowayOptionalProp $document 'effortLevel' $FlowayClaudeEffortLevel\n\n  $stage = \"$($script:ClaudeSettingsPath).floway-stage.$PID\"\n  try {\n    # The stage exists and is owner-only before any secret JSON is written.\n    [System.IO.File]::Create($stage).Dispose()\n    Protect-FlowayFile $stage\n    $json = $document | ConvertTo-Json -Depth 100\n    # Write UTF-8 without a BOM on every PowerShell version so downstream JSON\n    # parsers accept the file.\n    [System.IO.File]::WriteAllText($stage, $json, (New-Object System.Text.UTF8Encoding($false)))\n    $check = Get-Content -Raw -LiteralPath $stage | ConvertFrom-Json\n    if (($check.env.ANTHROPIC_BASE_URL -ne $FlowayBaseUrl) -or ($check.env.ANTHROPIC_AUTH_TOKEN -ne $FlowayApiKey)) {\n      Stop-FlowaySetup \"staged Claude settings failed validation.\"\n    }\n    # Windows PowerShell 5.1 only runs on Windows and has no $IsWindows\n    # automatic variable; PowerShell 6+ exposes it on every platform.\n    $runningOnWindows = ($PSVersionTable.PSVersion.Major -lt 6) -or $IsWindows\n    if ($script:ClaudeSettingsExisted -and $runningOnWindows) {\n      # File.Replace preserves the destination ACL, so tighten it first rather\n      # than letting a permissive historical DACL survive the atomic replace.\n      Protect-FlowayFile $script:ClaudeSettingsPath\n      [System.IO.File]::Replace($stage, $script:ClaudeSettingsPath, $null)\n    } else {\n      # Move-Item is an atomic same-filesystem rename on Unix and creates a new\n      # target on Windows. Windows replacing an existing target uses File.Replace.\n      Move-Item -LiteralPath $stage -Destination $script:ClaudeSettingsPath -Force\n    }\n  } catch {\n    if (Test-Path -LiteralPath $stage) { Remove-Item -LiteralPath $stage -Force }\n    Restore-FlowayClaudeSettings\n    throw\n  }\n}\n\n# Run a child process with its stdout and stderr redirected into in-process\n# pipes, bounded by a deadline. On timeout the whole process tree is terminated\n# and the call throws; otherwise the exit code and combined stdout+stderr are\n# returned. Arguments are fixed internal tokens, never external input.\nfunction Invoke-FlowayProcess {\n  param([string]$Exe, [string[]]$Arguments, [int]$TimeoutSeconds, [string]$TimeoutMessage)\n  $startInfo = New-Object System.Diagnostics.ProcessStartInfo\n  $startInfo.FileName = $Exe\n  $startInfo.UseShellExecute = $false\n  $startInfo.CreateNoWindow = $true\n  $startInfo.RedirectStandardOutput = $true\n  $startInfo.RedirectStandardError = $true\n  # ArgumentList is unavailable in Windows PowerShell 5.1. These arguments are\n  # fixed internal tokens, so quoting them with ProcessStartInfo.Arguments is\n  # safe and keeps external input out of the child command line.\n  $startInfo.Arguments = ($Arguments | ForEach-Object { '\"' + $_.Replace('\"', '\\\"') + '\"' }) -join ' '\n  $process = New-Object System.Diagnostics.Process\n  $process.StartInfo = $startInfo\n  if (-not $process.Start()) { Stop-FlowaySetup \"failed to start $Exe.\" }\n  $stdoutTask = $process.StandardOutput.ReadToEndAsync()\n  $stderrTask = $process.StandardError.ReadToEndAsync()\n  if (-not $process.WaitForExit($TimeoutSeconds * 1000)) {\n    Stop-FlowayProcessTree $process\n    $process.WaitForExit()\n    Stop-FlowaySetup $(if ($TimeoutMessage) { $TimeoutMessage } else { \"$Exe timed out after $TimeoutSeconds seconds.\" })\n  }\n  $stdout = $stdoutTask.GetAwaiter().GetResult()\n  $stderr = $stderrTask.GetAwaiter().GetResult()\n  [PSCustomObject]@{ ExitCode = $process.ExitCode; Output = ($stdout + $stderr) }\n}\n\nfunction Invoke-FlowayClaudeVerify {\n  param([string]$Exe)\n  $document = Get-Content -Raw -LiteralPath $script:ClaudeSettingsPath | ConvertFrom-Json\n  if (($document.env.ANTHROPIC_BASE_URL -ne $FlowayBaseUrl) -or ($document.env.ANTHROPIC_AUTH_TOKEN -ne $FlowayApiKey)) {\n    Stop-FlowaySetup \"the written Claude settings did not reparse as expected.\"\n  }\n\n  $timeoutSeconds = if ($env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS) { [int]$env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS } else { 30 }\n  $version = Invoke-FlowayProcess -Exe $Exe -Arguments @('--version') -TimeoutSeconds $timeoutSeconds -TimeoutMessage '``claude --version`` timed out.'\n  if ($version.ExitCode -ne 0) { Stop-FlowaySetup \"``claude --version`` failed.\" }\n  Write-FlowayInfo \"Claude Code version: $($version.Output.Trim())\"\n\n  $headers = @{\n    'Authorization'     = \"Bearer $FlowayApiKey\"\n    'x-api-key'         = $FlowayApiKey\n    'anthropic-version' = '2023-06-01'\n  }\n  $modelUri = ($FlowayBaseUrl.TrimEnd('/')) + '/v1/models'\n  try {\n    Invoke-WebRequest -Uri $modelUri -Headers $headers -Method Get -UseBasicParsing -TimeoutSec 30 | Out-Null\n  } catch {\n    Stop-FlowaySetup \"could not reach the authenticated model directory at $modelUri\"\n  }\n  Write-FlowaySuccess \"reached the authenticated model directory (no inference issued).\"\n\n  $doctorHelp = Invoke-FlowayProcess -Exe $Exe -Arguments @('doctor', '--help') -TimeoutSeconds $timeoutSeconds -TimeoutMessage 'claude doctor capability check timed out.'\n  if ($doctorHelp.ExitCode -eq 0) {\n    $doctor = Invoke-FlowayProcess -Exe $Exe -Arguments @('doctor') -TimeoutSeconds $timeoutSeconds -TimeoutMessage 'claude doctor timed out.'\n    if ($doctor.ExitCode -ne 0) {\n      Write-FlowayError \"claude doctor reported a problem:\"\n      Write-FlowayCaptured $doctor.Output\n      throw 'floway-handled'\n    }\n    Write-FlowaySuccess \"claude doctor reported no blocking issues.\"\n  } elseif ($doctorHelp.Output -match '(?i)(unknown|unrecognized|invalid|no such).*(command|subcommand).*doctor|doctor.*(unknown|unrecognized|invalid).*(command|subcommand)') {\n    Write-FlowayInfo \"this Claude Code build has no doctor command; skipping that check.\"\n  } else {\n    Write-FlowayError \"claude doctor capability check failed:\"\n    Write-FlowayCaptured $doctorHelp.Output\n    throw 'floway-handled'\n  }\n}\n\n# Configure Claude Code as one transactional unit. Verification failure rolls\n# back the settings write; a freshly installed CLI is never uninstalled.\nfunction Set-FlowayClaude {\n  Write-FlowayPhase 'Claude Code'\n  # Ref: https://docs.claude.com/en/docs/claude-code/troubleshoot-install\n  $candidates = @(\n    (Join-Path $HOME '.local/bin/claude'),\n    (Join-Path $HOME '.local/bin/claude.exe'),\n    (Join-Path $HOME '.claude/local/claude')\n  )\n  if ($env:USERPROFILE) { $candidates += (Join-Path $env:USERPROFILE '.local\\bin\\claude.exe') }\n  $exe = Get-FlowayCliExe -Name claude -Label 'Claude Code' -Candidates $candidates\n  if (-not $exe) {\n    Write-FlowayStep \"Claude Code CLI not found; installing the official build\"\n    Install-FlowayClaude\n    $exe = Get-FlowayCliExe -Name claude -Label 'Claude Code' -Candidates $candidates\n    if (-not $exe) { Stop-FlowaySetup \"Claude Code CLI is unavailable and could not be installed.\" }\n  }\n  Write-FlowayClaudeSettings\n  try {\n    Invoke-FlowayClaudeVerify $exe\n  } catch {\n    Write-FlowayWarn \"Claude Code verification failed; rolling back settings.\"\n    Restore-FlowayClaudeSettings\n    throw\n  }\n  Write-FlowaySuccess \"Claude Code configured.\"\n}\n\n# --- Codex ------------------------------------------------------------------\n\n# Install the official user-local Codex build. CODEX_NON_INTERACTIVE keeps the\n# installer from prompting. The FLOWAY_INSTALLER_TEST_INSTALL_CODEX_SCRIPT hook —\n# read from the ambient environment, never emitted by the gateway — substitutes\n# a fake installer under test.\nfunction Install-FlowayCodex {\n  $hadNonInteractive = Test-Path Env:CODEX_NON_INTERACTIVE\n  $previousNonInteractive = $env:CODEX_NON_INTERACTIVE\n  try {\n    $env:CODEX_NON_INTERACTIVE = 'true'\n    if ($env:FLOWAY_INSTALLER_TEST_INSTALL_CODEX_SCRIPT) {\n      $timeoutSeconds = if ($env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS) { [int]$env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS } else { 120 }\n      $installer = Invoke-FlowayProcess -Exe $env:FLOWAY_INSTALLER_TEST_INSTALL_CODEX_SCRIPT -Arguments @() -TimeoutSeconds $timeoutSeconds\n      if ($installer.ExitCode -ne 0) { Stop-FlowaySetup \"the test codex installer hook failed.\" }\n      return\n    }\n    # Match Codex's documented Windows invocation, including its process-scoped\n    # ExecutionPolicy override. This does not persist a policy change.\n    # Ref: https://github.com/openai/codex/blob/9e552e9d15ba52bed7077d5357f3e18e330f8f38/README.md#L23-L26\n    $installerUri = if ($env:FLOWAY_INSTALLER_TEST_CODEX_URL) { $env:FLOWAY_INSTALLER_TEST_CODEX_URL } else { 'https://chatgpt.com/codex/install.ps1' }\n    Invoke-FlowayRemoteInstaller -Uri $installerUri -BypassExecutionPolicy\n  } finally {\n    if ($hadNonInteractive) { $env:CODEX_NON_INTERACTIVE = $previousNonInteractive }\n    else { Remove-Item Env:CODEX_NON_INTERACTIVE -ErrorAction SilentlyContinue }\n  }\n}\n\n# Back up the config and provider token before any mutation, recording the\n# absence of each so rollback can distinguish \"restore\" from \"remove\".\nfunction Backup-FlowayCodexFiles {\n  $script:CodexConfigExisted = $false\n  $script:CodexTokenExisted = $false\n  $script:CodexConfigBackup = $null\n  $script:CodexTokenBackup = $null\n  # DateTimeOffset.ToUnixTimeMilliseconds is unavailable on the .NET Framework\n  # version bundled with the Windows PowerShell 5.1 baseline.\n  $stamp = [long]([DateTimeOffset]::UtcNow - [DateTimeOffset]'1970-01-01T00:00:00Z').TotalMilliseconds\n  if (Test-Path -LiteralPath $script:CodexConfigPath) {\n    $script:CodexConfigExisted = $true\n    $script:CodexConfigBackup = \"$($script:CodexConfigPath).floway-backup.$stamp.$PID\"\n    Copy-Item -LiteralPath $script:CodexConfigPath -Destination $script:CodexConfigBackup\n  }\n  if (Test-Path -LiteralPath $script:CodexTokenPath) {\n    $script:CodexTokenExisted = $true\n    $script:CodexTokenBackup = \"$($script:CodexTokenPath).floway-backup.$stamp.$PID\"\n    try {\n      Copy-Item -LiteralPath $script:CodexTokenPath -Destination $script:CodexTokenBackup\n      Protect-FlowayFile $script:CodexTokenBackup\n    } catch {\n      if (Test-Path -LiteralPath $script:CodexTokenBackup) {\n        Remove-Item -LiteralPath $script:CodexTokenBackup -Force\n      }\n      $script:CodexTokenBackup = $null\n      throw\n    }\n  }\n}\n\nfunction Restore-FlowayCodexFiles {\n  Restore-FlowayManagedFile -Existed $script:CodexConfigExisted -Backup $script:CodexConfigBackup -Path $script:CodexConfigPath -OriginalLabel 'file' -CreatedLabel 'Codex config'\n  Restore-FlowayManagedFile -Existed $script:CodexTokenExisted -Backup $script:CodexTokenBackup -Path $script:CodexTokenPath -OriginalLabel 'provider token' -CreatedLabel 'Codex provider token'\n}\n\n# Drive `codex app-server` over redirected stdin/stdout/stderr: initialize ->\n# initialized -> config/batchWrite. stderr is drained asynchronously so a chatty\n# server cannot fill the pipe buffer and deadlock. Each response read is bounded\n# by the remaining deadline; a timeout terminates the process tree. Unrelated\n# notifications are demultiplexed by id. Returns the batchWrite result object.\nfunction Invoke-FlowayCodexAppServerBatchWrite {\n  param([string]$Exe, $Edits, [int]$TimeoutSeconds)\n  $startInfo = New-Object System.Diagnostics.ProcessStartInfo\n  $startInfo.FileName = $Exe\n  $startInfo.Arguments = 'app-server --listen stdio://'\n  $startInfo.UseShellExecute = $false\n  $startInfo.CreateNoWindow = $true\n  $startInfo.RedirectStandardInput = $true\n  $startInfo.RedirectStandardOutput = $true\n  $startInfo.RedirectStandardError = $true\n  $process = New-Object System.Diagnostics.Process\n  $process.StartInfo = $startInfo\n  if (-not $process.Start()) { Stop-FlowaySetup \"failed to start the Codex app-server.\" }\n  $stderrTask = $process.StandardError.ReadToEndAsync()\n  $watch = [System.Diagnostics.Stopwatch]::StartNew()\n  $budgetMs = $TimeoutSeconds * 1000\n  $result = $null\n  try {\n    $readMatching = {\n      param([int]$WantId)\n      while ($true) {\n        $remaining = $budgetMs - $watch.ElapsedMilliseconds\n        if ($remaining -le 0) { Stop-FlowaySetup \"the Codex app-server timed out before confirming the configuration.\" }\n        $task = $process.StandardOutput.ReadLineAsync()\n        if (-not $task.Wait([int]$remaining)) { Stop-FlowaySetup \"the Codex app-server timed out before confirming the configuration.\" }\n        $line = $task.GetAwaiter().GetResult()\n        if ($null -eq $line) { Stop-FlowaySetup \"the Codex app-server exited before confirming the configuration.\" }\n        if ([string]::IsNullOrWhiteSpace($line)) { continue }\n        try { $msg = $line | ConvertFrom-Json } catch { Stop-FlowaySetup \"the Codex app-server returned a malformed response.\" }\n        if ($msg.id -ne $WantId) { continue }\n        if ($null -ne $msg.error) { Stop-FlowaySetup \"the Codex app-server reported an error writing the configuration.\" }\n        return $msg.result\n      }\n    }\n    $initReq = @{ jsonrpc = '2.0'; id = 1; method = 'initialize'; params = @{ clientInfo = @{ name = 'floway-setup'; title = $null; version = '1' }; capabilities = $null } } | ConvertTo-Json -Depth 10 -Compress\n    $process.StandardInput.WriteLine($initReq)\n    [void](& $readMatching 1)\n    $process.StandardInput.WriteLine('{\"jsonrpc\":\"2.0\",\"method\":\"initialized\"}')\n    $batchReq = @{ jsonrpc = '2.0'; id = 2; method = 'config/batchWrite'; params = @{ edits = $Edits } } | ConvertTo-Json -Depth 10 -Compress\n    $process.StandardInput.WriteLine($batchReq)\n    $result = (& $readMatching 2)\n  } finally {\n    try { $process.StandardInput.Close() } catch { }\n    if (-not $process.WaitForExit(1000)) {\n      Stop-FlowayProcessTree $process\n      $process.WaitForExit()\n    }\n    $null = $stderrTask.GetAwaiter().GetResult()\n  }\n  return $result\n}\n\n# Build the base-config edit batch and write it through the app-server. Model\n# and effort are opaque, forwarded verbatim, and cleared with JSON null ($null)\n# when unset. A batch status of `ok` or `okOverridden` confirms the intended\n# base config; `okOverridden` is reported with its non-secret layer metadata.\nfunction Write-FlowayCodexConfig {\n  param([string]$Exe)\n  $codexBase = ($FlowayBaseUrl.TrimEnd('/')) + '/azure-api.codex'\n  $runningOnWindows = ($PSVersionTable.PSVersion.Major -lt 6) -or $IsWindows\n  $auth = if ($runningOnWindows) {\n    [ordered]@{\n      command = 'powershell'\n      args = @('-NoProfile', '-Command', '$h = if ($env:CODEX_HOME) { $env:CODEX_HOME } else { Join-Path $HOME ''.codex'' }; [IO.File]::ReadAllText((Join-Path $h ''floway-token''))')\n    }\n  } else {\n    [ordered]@{\n      command = 'sh'\n      args = @('-c', 'cat \"${CODEX_HOME:-$HOME/.codex}/floway-token\"')\n    }\n  }\n  # Command auth opts a provider into online model refresh. The actor marker\n  # enables Codex's client-owned search and image extensions for this provider.\n  # https://github.com/openai/codex/blob/1bbdb32789e1f79932df44941236ea3658f6e965/codex-rs/models-manager/src/manager.rs#L413-L415\n  # https://github.com/openai/codex/blob/1bbdb32789e1f79932df44941236ea3658f6e965/codex-rs/model-provider-info/src/lib.rs#L396-L408\n  $edits = @(\n    @{ keyPath = 'model_provider'; mergeStrategy = 'replace'; value = 'floway' },\n    @{ keyPath = 'model_providers.floway.name'; mergeStrategy = 'replace'; value = 'Floway' },\n    @{ keyPath = 'model_providers.floway.base_url'; mergeStrategy = 'replace'; value = $codexBase },\n    @{ keyPath = 'model_providers.floway.auth'; mergeStrategy = 'replace'; value = $auth },\n    @{ keyPath = 'model_providers.floway.wire_api'; mergeStrategy = 'replace'; value = 'responses' },\n    @{ keyPath = 'model_providers.floway.supports_websockets'; mergeStrategy = 'replace'; value = $true },\n    @{ keyPath = 'model_providers.floway.http_headers'; mergeStrategy = 'replace'; value = @{ 'x-openai-actor-authorization' = '1' } },\n    @{ keyPath = 'features.apps'; mergeStrategy = 'replace'; value = $false },\n    @{ keyPath = 'features.standalone_web_search'; mergeStrategy = 'replace'; value = $true },\n    @{ keyPath = 'model'; mergeStrategy = 'replace'; value = $FlowayCodexModel },\n    @{ keyPath = 'model_reasoning_effort'; mergeStrategy = 'replace'; value = $FlowayCodexReasoningEffort }\n  )\n  $timeoutSeconds = if ($env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS) { [int]$env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS } else { 60 }\n  $result = Invoke-FlowayCodexAppServerBatchWrite -Exe $Exe -Edits $edits -TimeoutSeconds $timeoutSeconds\n  $status = [string]$result.status\n  if ($status -eq 'ok') {\n    Write-FlowaySuccess \"Codex base configuration written.\"\n  } elseif ($status -eq 'okOverridden') {\n    $message = if ($result.overriddenMetadata -and $result.overriddenMetadata.message) { [string]$result.overriddenMetadata.message } else { 'an override layer applies' }\n    $layer = 'unknown'\n    if ($result.overriddenMetadata -and $result.overriddenMetadata.overridingLayer -and $result.overriddenMetadata.overridingLayer.name) {\n      $layer = [string]$result.overriddenMetadata.overridingLayer.name.type\n    }\n    Write-FlowayWarn \"Codex base configuration written, but a higher-precedence layer overrides it ($message; layer: $layer).\"\n  } else {\n    Stop-FlowaySetup \"the Codex app-server did not confirm the configuration (status: $status).\"\n  }\n}\n\n# Store the Floway API key as a provider-scoped command-auth token. The private\n# stage is validated byte-for-byte, then atomically replaced. auth.json is an\n# account-owned Codex file and is never read or changed here.\nfunction Write-FlowayCodexToken {\n  $stage = \"$($script:CodexTokenPath).floway-stage.$PID\"\n  try {\n    [System.IO.File]::Create($stage).Dispose()\n    Protect-FlowayFile $stage\n    [System.IO.File]::WriteAllText($stage, $FlowayApiKey, (New-Object System.Text.UTF8Encoding($false)))\n    if ([System.IO.File]::ReadAllText($stage) -cne $FlowayApiKey) {\n      Stop-FlowaySetup \"staged Codex provider token failed validation.\"\n    }\n    $runningOnWindows = ($PSVersionTable.PSVersion.Major -lt 6) -or $IsWindows\n    if ($script:CodexTokenExisted -and $runningOnWindows) {\n      # File.Replace preserves the destination ACL, so tighten it first.\n      Protect-FlowayFile $script:CodexTokenPath\n      [System.IO.File]::Replace($stage, $script:CodexTokenPath, $null)\n    } else {\n      Move-Item -LiteralPath $stage -Destination $script:CodexTokenPath -Force\n    }\n  } catch {\n    if (Test-Path -LiteralPath $stage) { Remove-Item -LiteralPath $stage -Force }\n    throw\n  }\n}\n\n# Read the gateway's authenticated Codex model directory. No inference request\n# is issued. Transport/auth and JSON-shape failures remain distinct from a valid\n# catalog that simply lacks the selected model; none of the errors carries the\n# in-process Authorization header.\nfunction Read-FlowayCodexModelCatalog {\n  $headers = @{ 'Authorization' = \"Bearer $FlowayApiKey\" }\n  $uri = ($FlowayBaseUrl.TrimEnd('/')) + '/azure-api.codex/models'\n  try {\n    $response = Invoke-WebRequest -Uri $uri -Headers $headers -Method Get -UseBasicParsing -TimeoutSec 30\n  } catch {\n    Stop-FlowaySetup \"could not reach the authenticated Codex model directory at $uri\"\n  }\n  try {\n    $body = [string]$response.Content | ConvertFrom-Json\n  } catch {\n    Stop-FlowaySetup \"the authenticated Codex model directory did not return valid JSON.\"\n  }\n  if (($body -isnot [System.Management.Automation.PSCustomObject]) -or ($body.PSObject.Properties.Name -notcontains 'models') -or ($body.models -isnot [System.Array])) {\n    Stop-FlowaySetup \"the authenticated Codex model directory returned an invalid catalog shape.\"\n  }\n  $slugs = @()\n  foreach ($model in $body.models) {\n    if (($model -isnot [System.Management.Automation.PSCustomObject]) -or ($model.PSObject.Properties.Name -notcontains 'slug') -or ($model.slug -isnot [string])) {\n      Stop-FlowaySetup \"the authenticated Codex model directory returned an invalid catalog shape.\"\n    }\n    $slugs += [string]$model.slug\n  }\n  return $slugs\n}\n\n# Verify Codex without inference: compare the provider token without printing\n# it, print the raw CLI version, and reach the authenticated model directory\n# (confirming the selected model when one is set).\nfunction Invoke-FlowayCodexVerify {\n  param([string]$Exe)\n  if ([System.IO.File]::ReadAllText($script:CodexTokenPath) -cne $FlowayApiKey) {\n    Stop-FlowaySetup \"the written Codex provider token did not reparse as expected.\"\n  }\n  $timeoutSeconds = if ($env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS) { [int]$env:FLOWAY_INSTALLER_TEST_TIMEOUT_SECONDS } else { 30 }\n  $version = Invoke-FlowayProcess -Exe $Exe -Arguments @('--version') -TimeoutSeconds $timeoutSeconds -TimeoutMessage '``codex --version`` timed out.'\n  if ($version.ExitCode -ne 0) { Stop-FlowaySetup \"``codex --version`` failed.\" }\n  Write-FlowayInfo \"Codex version: $($version.Output.Trim())\"\n  $modelSlugs = @(Read-FlowayCodexModelCatalog)\n  if ($FlowayCodexModel -and ($modelSlugs -notcontains $FlowayCodexModel)) {\n    Stop-FlowaySetup \"the selected Codex model $FlowayCodexModel is not in the gateway catalog.\"\n  }\n  Write-FlowaySuccess \"reached the authenticated Codex model directory (no inference issued).\"\n}\n\n# Configure Codex as one transactional unit. The config and provider token are\n# backed up first; a write or verification failure restores both (or removes\n# newly created files). A freshly installed CLI is never uninstalled.\nfunction Set-FlowayCodex {\n  Write-FlowayPhase 'Codex'\n  # Ref: https://github.com/openai/codex/blob/main/scripts/install/install.sh\n  $candidates = @(\n    (Join-Path $HOME '.local/bin/codex'),\n    (Join-Path $HOME '.local/bin/codex.exe')\n  )\n  if ($env:USERPROFILE) { $candidates += (Join-Path $env:USERPROFILE '.local\\bin\\codex.exe') }\n  $exe = Get-FlowayCliExe -Name codex -Label Codex -Candidates $candidates\n  if (-not $exe) {\n    Write-FlowayStep \"Codex CLI not found; installing the official build\"\n    Install-FlowayCodex\n    $exe = Get-FlowayCliExe -Name codex -Label Codex -Candidates $candidates\n    if (-not $exe) { Stop-FlowaySetup \"Codex CLI is unavailable and could not be installed.\" }\n  }\n  $script:CodexHomeDir = if ($env:CODEX_HOME) { $env:CODEX_HOME } else { Join-Path $HOME '.codex' }\n  $script:CodexConfigPath = Join-Path $script:CodexHomeDir 'config.toml'\n  $script:CodexTokenPath = Join-Path $script:CodexHomeDir 'floway-token'\n  if (-not (Test-Path -LiteralPath $script:CodexHomeDir)) {\n    New-Item -ItemType Directory -Path $script:CodexHomeDir -Force | Out-Null\n  }\n  Backup-FlowayCodexFiles\n  try {\n    Write-FlowayCodexToken\n  } catch {\n    Write-FlowayWarn \"Codex provider-token staging failed; rolling back configuration and token.\"\n    Restore-FlowayCodexFiles\n    throw\n  }\n  try {\n    Write-FlowayCodexConfig -Exe $exe\n  } catch {\n    Write-FlowayWarn \"Codex configuration failed; rolling back configuration and token.\"\n    Restore-FlowayCodexFiles\n    throw\n  }\n  try {\n    Invoke-FlowayCodexVerify -Exe $exe\n  } catch {\n    Write-FlowayWarn \"Codex verification failed; rolling back configuration and token.\"\n    Restore-FlowayCodexFiles\n    throw\n  }\n  Write-FlowaySuccess \"Codex configured.\"\n}\n\n# --- run --------------------------------------------------------------------\n\n# Each agent's primary error is already reported at its detection site (the\n# 'floway-handled' marker), so the boundary only records the outcome. Any\n# unexpected exception that escaped without being reported is surfaced here,\n# redacted, so a failure is never silently swallowed.\n$script:ClaudeResult = 'skipped'\n$script:CodexResult = 'skipped'\n$overall = 0\n\nif ($FlowayInstallClaude) {\n  try {\n    Set-FlowayClaude\n    $script:ClaudeResult = 'configured'\n  } catch {\n    if ($_.Exception.Message -ne 'floway-handled') { Write-FlowayError (Protect-FlowaySecret ([string]$_.Exception.Message)) }\n    $script:ClaudeResult = 'failed'\n    $overall = 1\n  }\n}\n\nif ($FlowayInstallCodex) {\n  try {\n    Set-FlowayCodex\n    $script:CodexResult = 'configured'\n  } catch {\n    if ($_.Exception.Message -ne 'floway-handled') { Write-FlowayError (Protect-FlowaySecret ([string]$_.Exception.Message)) }\n    $script:CodexResult = 'failed'\n    $overall = 1\n  }\n}\n\nWrite-FlowayPhase 'Summary'\nWrite-FlowaySummaryEntry 'Claude Code' $script:ClaudeResult\nWrite-FlowaySummaryEntry 'Codex' $script:CodexResult\n\nexit $overall\n";
